                        and not (field.last_dom or field.last_dow or field.nth_dow)):
        field.values = None
    return field


def _parse(expr):
    """Parse expr into (minutes, hours, dom, months, dow) fields."""
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    text = expr.strip()
    if text.startswith("@"):
        try:
            text = _SHORTCUTS[text.lower()]
        except KeyError:
            raise ValueError(f"unknown shortcut {expr!r}") from None
    parts = re.split(r"[ \t]+", text)
    if len(parts) != 5:
        raise ValueError(f"expected 5 fields in {expr!r}")
    for part in parts:
        if not part.isascii() or not part.isprintable() or any(c.isspace() for c in part):
            raise ValueError(f"bad field {part!r} in {expr!r}")
    minutes = _parse_field(parts[0], 0, 59, None, "minute")
    hours = _parse_field(parts[1], 0, 23, None, "hour")
    dom = _parse_field(parts[2], 1, 31, None, "day of month")
    months = _parse_field(parts[3], 1, 12, _MONTH_NAMES, "month")
    dow = _parse_field(parts[4], 0, 7, _DAY_NAMES, "day of week")
    return minutes, hours, dom, months, dow


def _in(field, value):
    return field.values is None or value in field.values


def _day_allowed(dom, dow, date):
    days_in_month = calendar.monthrange(date.year, date.month)[1]
    weekday = (date.weekday() + 1) % 7  # Sunday is 0
    if dom.values is not None:
        ok = date.day in dom.values or (dom.last_dom and date.day == days_in_month)
        if not ok:
            return False
    if dow.values is not None:
        ok = weekday in dow.values
        if not ok and weekday in dow.last_dow and date.day + 7 > days_in_month:
            ok = True
        if not ok and (weekday, (date.day - 1) // 7 + 1) in dow.nth_dow:
            ok = True
        if not ok:
            return False
    return True


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    minutes, hours, dom, months, dow = _parse(expr)
    return (_in(minutes, when.minute) and _in(hours, when.hour)
            and _in(months, when.month) and _day_allowed(dom, dow, when.date()))


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    minutes, hours, dom, months, dow = _parse(expr)
    minute_list = sorted(minutes.values) if minutes.values is not None else range(60)
    hour_list = sorted(hours.values) if hours.values is not None else range(24)
    limit = after + _LIMIT
    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    date = start.date()
    first_time = (start.hour, start.minute)
    while True:
        if not _in(months, date.month):
            # skip straight to the first day of the next month
            year, month = (date.year + 1, 1) if date.month == 12 else (date.year, date.month + 1)
            date = datetime.date(year, month, 1)
            first_time = (0, 0)
            if datetime.datetime.combine(date, datetime.time()) > limit:
                return None
            continue
        if _day_allowed(dom, dow, date):
            for hour in hour_list:
                if hour < first_time[0]:
                    continue
                for minute in minute_list:
                    if (hour, minute) < first_time:
                        continue
                    candidate = datetime.datetime.combine(date, datetime.time(hour, minute))
                    if candidate > limit:
                        return None
                    return candidate
        date += datetime.timedelta(days=1)
        first_time = (0, 0)
        if datetime.datetime.combine(date, datetime.time()) > limit:
            return None
